const form=document.querySelector('#trade-brief');
if(form){const fields={company:'Company',role:'Business role',scope:'Products requested',units:'Kitchens / units',location:'Project location',timeline:'Timeline',schedule:'Cabinet / accessory schedule and notes',contact:'Contact',email:'Business email',phone:'Phone'};let brief='';form.addEventListener('input',()=>{document.querySelector('#trade-review').hidden=true;brief='';});form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));const summary=document.querySelector('#trade-summary');summary.replaceChildren();const lines=[];for(const [key,label]of Object.entries(fields)){const value=String(values[key]||'Not provided').trim();const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;summary.append(dt,dd);lines.push(label+': '+value);}brief='KABBY HOME — BUSINESS QUOTE REQUEST\n\n'+lines.join('\n\n')+'\n\nPlease review specifications, product availability, pricing and service scope with me. This brief is a request, not an order.';document.querySelector('#trade-email').href='mailto:info@amberleafhome.us?subject='+encodeURIComponent('Business cabinet / accessory quote — '+values.company)+'&body='+encodeURIComponent(brief);document.querySelector('#trade-review').hidden=false;document.querySelector('#trade-review').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});});document.querySelector('#trade-download').addEventListener('click',()=>{if(!brief)return;const url=URL.createObjectURL(new Blob([brief],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='kabby-home-business-project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
